page(dict(
 slug='weakties',
 title=T('새 일자리 소식은 왜 친한 친구가 아니라 얼굴만 아는 사람에게서 올까: 약한 유대의 힘', 'Why Do Job Tips Come from Acquaintances, Not Close Friends? The Strength of Weak Ties'),
 title_tag=T('약한 유대의 힘 · 시뮬라티오 랩', 'The Strength of Weak Ties · Simulatio Lab'),
 desc=T('친한 친구 무리에 얼굴만 아는 사람 몇 명을 이었더니 소식이 퍼지는 속도가 몇 배로 빨라지는 작은 세상 네트워크를, 슬라이더로 직접 돌려보세요.',
        'Run a small-world network yourself: add just a few acquaintances to tight friend circles and watch news reach everyone several times faster.'),
 lead=T('새 일자리 소식은 가장 친한 친구에게서 올 것 같습니다. 그런데 친한 친구들은 대개 서로도 아는 사이라 같은 소식만 돌고 돕니다. 이 모델에서는 서로 가까운 이웃끼리만 이어진 300명의 원에 먼 사람과 이은 선 약 18개(전체 연결의 2%)를 보태자, 소식이 90%에 퍼지는 시간이 58턴에서 16턴으로 줄어듭니다. 친구 무리는 거의 그대로인데 세상이 갑자기 작아집니다. 원 위의 사람을 눌러 그 사람부터 소식을 시작해 보세요.',
        'You would expect a job tip to come from your closest friends. But close friends mostly know each other, so the same news just circulates. In this model, 300 people in a ring are tied only to near neighbors; adding about 18 ties to far-away people (2% of all ties) cuts the time for news to reach 90% of people from 58 turns to 16. The friend circles barely change, yet the world suddenly gets small. Click a person on the ring to start the news from them.'),
 model=[T('<b>원 위의 사람들</b>이 각자 양옆 가까운 이웃 몇 명(기본 6명)과 이어져 있습니다. 서로 이웃의 이웃이라 친구 무리가 촘촘하게 겹칩니다. 소식은 이 무리를 따라 한 걸음씩 번져서 반대편까지 가는 데 오래 걸립니다.',
          '<b>People stand on a ring</b>, each tied to a few near neighbors on either side (6 by default). Neighbors share neighbors, so friend circles overlap tightly. News creeps along them step by step and takes a long time to reach the far side.'),
        T('이어진 선마다 확률 p로 한쪽 끝을 <b>원 어디든 무작위 먼 사람</b>으로 바꿉니다. 이것이 얼굴만 아는 사이, 곧 약한 연결입니다(보라색 선). p가 0이면 약한 연결이 없고, 1이면 모든 선이 무작위입니다.',
          'Each tie has probability p of having one end <b>moved to a random far-away person</b>. These are acquaintances, the weak ties (purple lines). With p = 0 there are none, and with p = 1 every tie is random.'),
        T('소식은 한 사람에서 시작합니다. 매 턴 소식을 아는 사람이 아직 모르는 이웃에게 전달 확률(기본 50%)로 전합니다. 90%가 알 때까지 걸린 턴을 재고, 여러 번 돌려 평균을 냅니다.',
          'The news starts with one person. Each turn, everyone who knows it tells each neighbor who does not, with the passing probability (50% by default). I measure the turns until 90% know it, averaged over many runs.'),
        T('<b>평균 거리</b>는 두 사람 사이 최단 경로의 평균 걸음 수, <b>친구 무리의 촘촘함</b>(군집계수)은 내 친구 둘이 서로도 친구일 비율의 평균입니다.',
          'The <b>average distance</b> is the mean number of steps on the shortest path between two people, and the <b>tightness of friend circles</b> (clustering coefficient) is the average chance that two of my friends are also friends.')],
 sliders=[('p', T('약한 연결 비율 p', 'Share of weak ties p'), 0, 11, 1, 5, T('0%부터 100%까지 열두 칸. 1~5% 구간을 천천히 만져 보세요', 'Twelve steps from 0% to 100%. Try the 1 to 5% range slowly')),
          ('n', T('사람 수', 'People'), 100, 500, 50, 300, T('많을수록 원이 커져서, 약한 연결이 없을 때 소식이 더 오래 걸려요', 'More people make a bigger ring, so news takes longer without weak ties')),
          ('k', T('가까운 이웃 수', 'Close neighbors'), 4, 10, 2, 6, T('한 사람이 이어진 가까운 이웃의 수(양옆 합계)', 'Close neighbors per person, both sides together')),
          ('q', T('전달 확률', 'Passing probability'), 20, 100, 10, 50, T('아는 사람이 한 턴에 이웃에게 소식을 전할 확률', 'Chance a person who knows passes it to a neighbor each turn'))],
 selects=[],
 reroll=T('같은 설정, 다른 네트워크', 'Same settings, different network'),
 sections=[
  dict(title=T('① 소식이 퍼지는 모습', '① Watching the News Spread'),
       p=T('원 위의 점이 사람, 가까운 이웃끼리는 회색 선, 먼 사람과 이은 약한 연결은 보라색 선입니다. 남색 점은 소식을 안 사람이고 진할수록 먼저 안 사람입니다. 소식이 약한 연결을 건너뛰면 그 선이 굵어집니다. 점을 누르면 그 사람부터 다시 시작합니다.',
           'Dots are people, gray lines are ties between near neighbors, and purple lines are weak ties to far-away people. Navy dots know the news, darker meaning earlier. When the news jumps across a weak tie, that line turns thick. Click a dot to restart from that person.'),
       id='c-net', rounded=True, anim=True, thumb=True,
       speeds=[('3', T('느리게', 'Slow')), ('6', T('보통', 'Normal')), ('14', T('빠르게', 'Fast'))], speed_default='6'),
  dict(title=T('② 거리는 급히 줄고 무리는 그대로', '② Distance Collapses, Circles Stay'),
       p=T('가로는 약한 연결의 비율(로그 눈금), 세로는 약한 연결이 없을 때를 100%로 놓은 값입니다. 파랑(평균 거리)은 1%만 되어도 절반 아래로 떨어지는데, 노랑(친구 무리의 촘촘함)은 거의 그대로입니다. 이 간격이 작은 세상입니다.',
           'The horizontal axis is the share of weak ties (log scale) and the vertical axis shows each value relative to no weak ties (100%). Blue (average distance) falls below half by 1%, while yellow (tightness of friend circles) barely moves. That gap is the small world.'),
       id='c-small'),
  dict(title=T('③ 소식이 퍼지는 속도 비교', '③ How Fast the News Spreads'),
       p=T('턴마다 소식을 아는 사람의 비율입니다(8번 평균). 회색은 약한 연결이 없을 때, 나머지는 약한 연결이 늘어난 경우이고, 검은 굵은 선이 지금 설정입니다. 점선은 90%입니다.',
           'The share of people who know the news at each turn (averaged over 8 runs). Gray is no weak ties, the others have more of them, and the thick black line is the current setting. The dotted line marks 90%.'),
       id='c-spread', legend=[leg('background:#8a93a6', '0%', '0%'), leg('background:#4f7cf0', '0.5%', '0.5%'), leg('background:#1fa463', '2%', '2%'), leg('background:#e0a100', '10%', '10%'), leg('background:#e5484d', '100%', '100%'), leg('background:#1b1f2a', '지금 설정', 'Current setting')]),
  dict(title=T('④ 약한 연결이 얼마나 필요할까', '④ How Many Weak Ties Do We Need?'),
       p=T('90%가 알 때까지 걸리는 턴을 약한 연결 비율별로 그렸습니다. 처음 몇 개가 가장 크게 줄여 주고, 그 뒤로는 점점 덜 줄어듭니다.',
           'Turns needed for 90% to know the news, by share of weak ties. The first few ties help most, and each further tie helps less.'),
       id='c-t90'),
 ],
 says=T('사람 300명, 가까운 이웃 6명, 전달 확률 50%에서 약한 연결이 없을 때 소식이 90%에 닿는 데 평균 58.1턴(40번 평균)이 걸렸습니다. 약한 연결 1%에서는 22.0턴, 2%(연결 900개 중 약 18개)에서는 16.2턴으로 3.6배 빨랐고, 5%에서는 11.8턴, 전부 무작위(100%)일 때는 6.2턴이었습니다. 평균 거리는 약한 연결이 없을 때 25.4걸음이었다가 1%에서 44%(11.2걸음), 2%에서 33%(8.4걸음)로 줄었지만, 친구 무리의 촘촘함은 같은 구간에서 각각 97%, 94%로 거의 그대로였습니다. 전달 확률 20%에서도 103.6턴에서 31.1턴으로, 사람 500명에서도 96.8턴에서 18.1턴으로 줄었습니다.',
        'With 300 people, 6 close neighbors and a 50% passing probability, news took an average of 58.1 turns (40-run average) to reach 90% of people without weak ties. With 1% weak ties it took 22.0 turns, and with 2% (about 18 of 900 ties) it took 16.2, which is 3.6 times faster; 5% gave 11.8 turns and fully random ties (100%) gave 6.2. The average distance fell from 25.4 steps with no weak ties to 44% (11.2 steps) at 1% and 33% (8.4 steps) at 2%, while the tightness of friend circles stayed at 97% and 94% of its starting value. At a 20% passing probability the time still fell from 103.6 to 31.1 turns, and with 500 people from 96.8 to 18.1.'),
 **{'not': T('실제 사회를 재현한 것이 아닙니다. 이 모델은 모두가 같은 수의 이웃을 갖고, 약한 연결이 똑같이 소식을 전한다는 이 프로젝트의 단순화된 가정으로 만들었습니다. 현실의 약한 연결은 덜 믿고, 덜 자주 연락하고, 소식을 덜 전할 수 있는데 여기서는 그 차이를 두지 않았습니다. 또 그라노베터의 주장은 일자리 정보가 나에게 닿는 경로에 관한 것입니다. 이 모델은 소식이 퍼지는 속도만 보여 줄 뿐 일자리를 얻는 데 약한 유대가 더 낫다는 것을 증명하지 않으며, 이후 연구 결과도 엇갈립니다. 친한 친구가 더 적극적으로 도와주는 경우도 있습니다.',
                'This does not reproduce real societies. It is this project\'s simplified model in which everyone has the same number of neighbors and weak ties pass news just as well as close ones. In reality weak ties may be trusted less, contacted less and pass news less, which is not modeled here. Granovetter\'s claim is about how job information reaches you. This model shows only how fast news spreads; it does not prove that weak ties are better for getting a job, and later studies are mixed. Close friends sometimes help more actively.')},
 theory=[('root', T('작은 세상 네트워크는 Watts &amp; Strogatz (1998), "Collective dynamics of \'small-world\' networks", <i>Nature</i> 393, 440-442에서 나왔고, 약한 유대라는 생각은 Granovetter (1973), "The Strength of Weak Ties", <i>American Journal of Sociology</i> 78(6), 1360-1380에서 나왔습니다. 가까운 이웃으로 이뤄진 격자에 무작위 연결 몇 개만 섞어도 평균 거리가 크게 줄어듭니다.',
                   'The small-world network comes from Watts &amp; Strogatz (1998), "Collective dynamics of \'small-world\' networks", <i>Nature</i> 393, 440-442, and the idea of weak ties from Granovetter (1973), "The Strength of Weak Ties", <i>American Journal of Sociology</i> 78(6), 1360-1380. Mixing a few random ties into a lattice of near neighbors sharply cuts the average distance.')),
         ('model', T('원 위의 n명이 각자 가까운 이웃 k명과 이어진 상태에서 시작해 연결마다 확률 p로 끝을 무작위로 바꿉니다. 이론적으로 p = 0에서 평균 거리는 약 <code>n/(2k)</code>, 군집계수는 <code>C(0) = 3(k−2)/(4(k−1))</code>이고, p가 작을 때 군집계수는 <code>C(p) ≈ C(0)(1−p)<sup>3</sup></code>로 근사됩니다(Barrat &amp; Weigt, 2000). 슬라이더 p, k, n이 각각 이 식의 p, k, n입니다.',
                     'Start with n people on a ring, each tied to k near neighbors, and move one end of each tie to a random person with probability p. In theory, at p = 0 the average distance is about <code>n/(2k)</code> and the clustering coefficient is <code>C(0) = 3(k−2)/(4(k−1))</code>; for small p the clustering is approximately <code>C(p) ≈ C(0)(1−p)<sup>3</sup></code> (Barrat &amp; Weigt, 2000). The sliders p, k and n are these same symbols.')),
         ('simplify', T('원 논문은 평균 거리와 군집계수만 다루고 소식 퍼짐은 이 프로젝트가 덧붙인 것입니다. 전달 확률, 한 사람에서 시작, 모든 연결이 같은 힘이라는 가정, 90% 기준, 사람 수 300과 이웃 6명은 이 프로젝트가 정한 값입니다. 연결의 세기나 신뢰는 모델에 없습니다.',
                        'The original paper covers only average distance and clustering; the news spreading is this project\'s addition. The passing probability, starting from one person, equal strength for all ties, the 90% criterion, and the defaults of 300 people and 6 neighbors are this project\'s choices. Tie strength and trust are not in the model.')),
         ('check', T('p = 0에서 시뮬레이션의 평균 거리는 25.4걸음으로 근사 n/(2k) = 25.0과 비슷했고, 군집계수는 0.600으로 이론값 0.600과 같았습니다. p = 2%에서 군집계수는 0.566으로 C(0)(1−p)<sup>3</sup> = 0.565와 맞았고, p = 20%에서도 0.322 대 0.307로 가까웠습니다(p가 클수록 근사가 어긋나 50%에서는 0.095 대 0.075). 소식 퍼짐은 이론값이 없어 시뮬레이션만으로 확인했습니다(<code>node tools/validate-weakties.js</code>).',
                     'At p = 0 the simulated average distance was 25.4 steps against the approximation n/(2k) = 25.0, and the clustering was 0.600, equal to the theoretical 0.600. At p = 2% the clustering was 0.566 against C(0)(1−p)<sup>3</sup> = 0.565, and at p = 20% 0.322 against 0.307; the approximation drifts for large p (0.095 against 0.075 at 50%). The news spreading has no theoretical benchmark, so it was checked by simulation only (<code>node tools/validate-weakties.js</code>).')),
         ('read', T('Granovetter (1973), "The Strength of Weak Ties", <i>American Journal of Sociology</i> 78(6); Watts &amp; Strogatz (1998), <i>Nature</i> 393; Barrat &amp; Weigt (2000), "On the properties of small-world network models", <i>European Physical Journal B</i> 13.',
                    'Granovetter (1973), "The Strength of Weak Ties", <i>American Journal of Sociology</i> 78(6); Watts &amp; Strogatz (1998), <i>Nature</i> 393; Barrat &amp; Weigt (2000), "On the properties of small-world network models", <i>European Physical Journal B</i> 13.'))],
 memo=[T('시뮬레이션은 시드 난수(mulberry32)를 쓰고 같은 시드면 같은 결과가 나옵니다. 평균 거리는 일부 출발점에서 너비 우선 탐색으로 구한 평균이고, ②와 ④는 설정마다 네트워크 6개, ③은 8개, 상단 숫자 카드는 14개를 만들어 평균을 냅니다.',
         'The simulation uses a seeded random generator (mulberry32), so the same seed gives the same result. Average distance comes from breadth-first search from a sample of starting people; charts ② and ④ average 6 networks per setting, ③ averages 8, and the top cards average 14.'),
       T('검증은 <code>node tools/validate-weakties.js</code>로 할 수 있습니다.',
         'You can verify with <code>node tools/validate-weakties.js</code>.')],
))
